import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Loading from '../../loading/Loading';
import './CompanyZapatos.css';
import CompanyMenu from '../Company_Menu/CompanyMenu';
import { getColores, getEmpresa, getTallas, getMarcas, setColores, setEmpresa, setTallas, setMarcas } from "../Company_Localstorang/Company_Localstorang";
import { Historial_Local, Guardar_Imagen } from '../../../Redux/Actions/Empresa/Actions-Empresa';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';
import { useNavigate } from 'react-router-dom';

// Firebase
import { getFirestore, collection, addDoc } from 'firebase/firestore';
import { getStorage, ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import appfirebase from '../../../credenciales';

const storange = getStorage(appfirebase);
const db = getFirestore(appfirebase);

const CompanyZapatos = () => {
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const colores = useSelector((state) => state.myReducer.COLORES || []);
    const empresa = useSelector((state) => state.myReducer.EMPRESA || []);
    const tallas = useSelector((state) => state.myReducer.TALLAS || []);
    const marcas = useSelector((state) => state.myReducer.MARCAS || []);
    const id = useSelector((state) => state.myReducer.id);

    useEffect(() => {
        const timer = setTimeout(() => {
            setLoading(false);
            dispatch(Historial_Local(getColores(), getTallas(), getMarcas(), getEmpresa()));
        }, 3000);

        return () => clearTimeout(timer);
    }, [dispatch]);

    const [formData, setFormData] = useState({
        color: '',
        talla: '',
        costo: '',
        marca: '',
        modelo: '',
        descripcion: '',
        calidad: '',
        url: ''
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleFileChange = async (e) => {
        const mail = getEmpresa().name;
        dispatch(Guardar_Imagen(mail));
        alert("datos " + id);

        const file = e.target.files[0];

        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData({ ...formData, url: reader.result });
            };
            reader.readAsDataURL(file);

            const refArchivo = ref(storange, `documentos/${file.name}`);
            await uploadBytes(refArchivo, file);
            const urle_descarfada = await getDownloadURL(refArchivo);
            setFormData({ url: urle_descarfada });
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log('Datos del zapato:', formData);
    };

    const HandleGuardar = async () => {
        const newZapto = {
            id_imagen: '',
            img: formData.url
        };

        // Guardaremos la imagen
        try {
            await addDoc(collection(db, "zapatos"), {
                ...newZapto
            });
        } catch (error) {
            console.log("error");
        }
    };

    return (
        <div>
            {loading ? <Loading /> : null}
            <CompanyMenu className="nav-menu" />
            <div className="body-zapatos">
                <h2>Crear Nuevo Zapato</h2>
                <form className="form-zapatos" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Color:</label>
                        <select
                            name="color"
                            value={formData.color}
                            onChange={handleChange}
                        >
                            <option value="">Seleccione un color</option>
                            {colores.map((color) => (
                                <option key={color.id} value={color.color}>
                                    {color.color}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="form-group">
                        <label>Talla:</label>
                        <div className='grupor-flex'>
                            <select
                                name="talla"
                                value={formData.talla}
                                onChange={handleChange}
                            >
                                <option value="">Seleccione una talla</option>
                                {tallas.map((t) => (
                                    <option key={t.id} value={t.talla}>
                                        {t.talla}
                                    </option>
                                ))}
                            </select>
                            <label className='btn-mas' onClick={hanldeAddTalla} title='Agregar una nueva talla'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Costo:</label>
                        <input
                            type="number"
                            name="costo"
                            value={formData.costo}
                            onChange={handleChange}
                        />
                    </div>
                    <div className="form-group">
                        <label>Marca:</label>
                        <div className='grupor-flex'>
                            <select
                                name="marca"
                                value={formData.marca}
                                onChange={handleChange}
                            >
                                <option value="">Seleccione una marca</option>
                                {marcas.map((m) => (
                                    <option key={m.id} value={m.marca}>
                                        {m.marca}
                                    </option>
                                ))}
                            </select>
                            <label className='btn-mas' title='Agregar una nueva marca'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Modelo:</label>
                        <input
                            type="text"
                            name="modelo"
                            value={formData.modelo}
                            onChange={handleChange}
                        />
                    </div>
                    <div className="form-group">
                        <label>Calidad:</label>
                        <div className='grupor-flex'>
                            <select
                                name="calidad"
                                value={formData.calidad}
                                onChange={handleChange}
                            >
                                <option value="">Seleccione</option>
                                <option value="AA">AA</option>
                                <option value="AAA">AAA</option>
                                <option value="Tipo Original">Tipo Original</option>
                                <option value="Original">Original</option>
                            </select>
                        </div>
                    </div>
                    <div className="form-group form-group-textarea">
                        <label>Descripción:</label>
                        <textarea
                            name="descripcion"
                            value={formData.descripcion}
                            onChange={handleChange}
                        ></textarea>
                    </div>
                    <div className="form-group form-group-textarea">
                        <label>URL cargada:</label>
                        <textarea
                            name="descripcion"
                            value={formData.url}
                            onChange={handleChange}
                        ></textarea>
                    </div>
                    <div className="form-group">
                        <label>Subir Imagen:</label>
                        <input
                            type="file"
                            accept="image/*"
                            onChange={handleFileChange}
                        />
                    </div>
                    {formData.url && (
                        <div className="form-group">
                            <label>Vista Previa:</label>
                            <img src={formData.url} alt="Vista previa" className="img-preview" />
                        </div>
                    )}
                    <div onClick={HandleGuardar}>Guardar Zapato</div>
                </form>
            </div>
        </div>
    );
};

export default CompanyZapatos;
